#!/bin/bash
# Task 123-w2-observer-proof-baseline -- meshsim sim/ WORKER2 (branch sim-w2).
# 1. The observer's proof (sim/planning/DECISIONS.md D5): the quick suite's 39 Java steps (run_tests.sh quick's, as
#    tools/run_quick.sh takes them) three ways: main 3f0e919's pristine sim/ref; sim-w2 03dee7a's sim/ref with the observer
#    off; the same with it on (-Dmeshsim.observe=FILE,0). Masked logs, exit codes and every chip's fingerprint compared
#    (sim/tests/ref/prove_observer.sh, 12 at a time). The firmware is prebuilt in the kit (riscv gcc 13.2).
# 2. Then, with part 1 finished and nothing else running, the baseline (D8, D13): ReplayBench (sim-step-cost 8fd1ecd, code
#    = b7655df as Quest 120) on segment 0 of evm-zone-29, windows 0-63, 3 repeats per JVM, 3 GB heaps: 1 JVM on CPUs 0-1
#    (one P-core), then 12 JVMs on CPUs 0-11, then 16 on CPUs 0-15 (sim/tests/ref/baseline.sh): us per chip-cycle per JVM,
#    chip-cycles per second in total, the load, peak RSS, per-CPU busy shares and the E-cores' part.
# Inputs only read (the w9 delivery of evm-zone-29, checked first). Writes only results/123-w2-observer-proof-baseline/.
# Scratch in /tmp, removed first and at the end; safe to re-run from the start. Expected ~25 min.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/123-w2-observer-proof-baseline; mkdir -p "$RES"
DATA=$HOME/data; [ -d "$DATA/w9-deliveries" ] || DATA=$REPO/data
W=/tmp/w2-123; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "4267e70464c2a4888e22e97269e6909065cf5ab4e6a4d4bc07f84fad8bd19cc3" ] || { echo "kit sha256 mismatch (want 4267e70464c2a4888e22e97269e6909065cf5ab4e6a4d4bc07f84fad8bd19cc3)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cat "$W/VERSION"; echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1; free -g | head -2
D9=$DATA/w9-deliveries; S9=7142e894c80a0c9d491f21c852a942885e0abd97cfe6aefd0101d716824e138f
[ "$(sha256sum "$D9/evm-zone-29.manifest.json" 2>/dev/null | cut -d' ' -f1)" = "$S9" ] && [ "$(cat "$D9/evm-zone-29.COMPLETE" 2>/dev/null)" = "$S9" ] \
  || { echo "evm-zone-29: the delivery isn't complete or differs (tasks 103/104)"; exit 2; }
echo "evm-zone-29: input checked ($D9)"

# ---- 1. the observer's proof
a=$(date +%s)
P=12 bash "$W/prove_observer.sh" "$W/p/sim/ref/meshsim" "$W/proof"; PR=$?
cp "$W/proof/VERDICTS.txt" "$RES/VERDICTS.txt"; cat "$RES/VERDICTS.txt"
echo "proof: exit $PR, $(($(date +%s) - a)) s"
rm -f "$W"/proof/*.trace
tar -czf "$RES/proof-logs.tgz" -C "$W/proof" . 2>/dev/null

# ---- 2. the baseline, alone on the box
pgrep -u "$(id -u)" -x java > /dev/null && { echo "a JVM is still running before the baseline"; pgrep -a -u "$(id -u)" -x java; }
cd "$W/b/wip/meshsim" || exit 2
java -Xmx2g -cp build:build/gold ConvertDelivery "$D9" "$W/v1261" evm-zone-29 > "$RES/convert.log" 2>&1 || { echo "conversion failed"; tail -5 "$RES/convert.log"; exit 1; }
tail -1 "$RES/convert.log"
uptime
bash "$W/baseline.sh" "$W/b/wip/meshsim" "$W/v1261" "$W/bl"; BR=$?
cp "$W/bl/BASELINE.txt" "$RES/"; cp "$W"/bl/*.jvms "$RES/" 2>/dev/null
tar -czf "$RES/baseline-logs.tgz" -C "$W/bl" . 2>/dev/null
echo "baseline: exit $BR; $(date -u)"
rm -rf "$W"
[ $PR = 0 ] && [ $BR = 0 ]; exit $?
